INSERT INTO biz_mini_content(content_key,content_type,title,content_json,status,create_by,update_by) SELECT 'rules.points','rule','雄森酒业活动规则','[{"title":"消费积分","text":"小程序内消费，每实付满1元获得1积分，不足1元部分不计。订单确认收货或自提核销后入账；退款对应积分按实际退款情况冲回。"},{"title":"积分兑换","text":"500积分兑换萌虎体验官券1张（价值60元，动物园内萌虎城堡使用）；1000积分兑换动物园门票1张（价值99元）；20000积分兑换雄景酒店高级房1间1晚（价值499元，含双早）。"},{"title":"电子券使用","text":"兑换后在个人中心“我的奖品”领取电子券，按券面规则提前预约使用。"}]','0','xiongsen-20261031','xiongsen-20261031' WHERE @apply_xs_catalog=1 ON DUPLICATE KEY UPDATE title=VALUES(title),content_json=VALUES(content_json),status='0',update_by=VALUES(update_by);
INSERT INTO biz_mini_content(content_key,content_type,title,content_json,status,create_by,update_by) SELECT 'rules.draw','rule','雄森酒业活动规则','[{"title":"雄酒抽奖","text":"本期共20000份奖品：10000张动物园门票（每张价值99元），以及10000份99积分奖励。每个有效活动码限领取一次，100%有奖。"},{"title":"自动发放","text":"抽中门票自动存入“我的奖品”；未抽中门票获得99积分，自动存入积分账户。已发放奖励和积分明细可在个人中心查看。"}]','0','xiongsen-20261031','xiongsen-20261031' WHERE @apply_xs_catalog=1 ON DUPLICATE KEY UPDATE title=VALUES(title),content_json=VALUES(content_json),status='0',update_by=VALUES(update_by);
INSERT INTO biz_mini_content(content_key,content_type,title,content_json,status,create_by,update_by) SELECT 'rules.promotion','rule','雄森酒业活动规则','[{"title":"推荐奖励","text":"生成专属商品分享链接或海报分享给好友，系统追踪有效推荐关系。直接推荐人获得好友订单实付总金额5%的佣金，不叠加多级佣金。"},{"title":"结算与收款","text":"好友确认收货7天后自动发起微信佣金转账。微信要求确认收款时，请在推广中心点击确认收款；到账以微信回执为准。退款与售后中的佣金暂停结算，已确认退款按实际金额冲回或抵扣。"}]','0','xiongsen-20261031','xiongsen-20261031' WHERE @apply_xs_catalog=1 ON DUPLICATE KEY UPDATE title=VALUES(title),content_json=VALUES(content_json),status='0',update_by=VALUES(update_by);
INSERT INTO biz_mini_content(content_key,content_type,title,content_json,status,create_by,update_by) SELECT 'rules.shipping','rule','雄森酒业活动规则','[{"title":"包邮配送","text":"小程序商城商品包邮配送。请准确填写收货地址，签收时核对商品数量和包装。"}]','0','xiongsen-20261031','xiongsen-20261031' WHERE @apply_xs_catalog=1 ON DUPLICATE KEY UPDATE title=VALUES(title),content_json=VALUES(content_json),status='0',update_by=VALUES(update_by);
