-- Source: 小程序奖品积分说明(1).docx; user confirmed 10000 tickets + 10000 point awards.
-- No stock, photographs, sales figures, customer data or credentials are fabricated.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS biz_rule_release(release_code varchar(64) PRIMARY KEY,applied_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
START TRANSACTION;
SET @apply_xs_catalog=(SELECT COUNT(*)=0 FROM biz_rule_release WHERE release_code='xiongsen-catalog-20261031');
UPDATE biz_product SET status='1' WHERE @apply_xs_catalog=1 AND product_code IN ('classic','mellow','double','gift','PRO_QAt9MSNcrPOeubBO');
UPDATE biz_point_rule SET points=1,daily_limit=-1,validity_days=0,status='0',rule_json=JSON_OBJECT('per_cent',1) WHERE @apply_xs_catalog=1 AND rule_code='order_paid';
UPDATE biz_point_rule SET status='1' WHERE @apply_xs_catalog=1 AND rule_code IN ('invite_register','daily_sign','ranking');
UPDATE biz_promotion_config SET max_level=1,customer_rate_bp=500,staff_rate_bp=500,level_rates_json=JSON_OBJECT('customer',JSON_ARRAY(500),'staff',JSON_ARRAY(500)),settlement_days=7,min_withdraw_cent=1,status='0' WHERE @apply_xs_catalog=1 AND config_id=1;
UPDATE biz_shipping_template SET template_name='商城包邮',free_threshold_cent=0,base_fee_cent=0,extra_fee_cent=0,status='0' WHERE @apply_xs_catalog=1 AND template_id=1;
COMMIT;
